# Generated by GitHub Copilot - Oct-05-2026
def analysis_folder(value):
    """Select an explicit run or the only extracted run; never pick ambiguously."""
    folder=Path(value).expanduser().resolve()
    if not folder.is_dir():
        raise ValueError('Use uma pasta extraida, nao um ZIP: '+str(folder))
    if any((folder/name).is_file() for name in ('run_manifest.json','analysis_summary.json','analysis_quality.json','analysis.json')):
        return folder
    runs=sorted({path.parent for path in folder.glob('analysis/*/run_manifest.json')})
    if len(runs)!=1:
        raise ValueError('Especifique a pasta de uma unica analise; encontrados '+str(len(runs)))
    return runs[0]


# Generated by GitHub Copilot - Oct-05-2026
def read_optional(folder,name,maximum=32*1024**2):
    """Treat absent or oversized review evidence as unavailable, not measured zero."""
    path=folder/name
    if not path.is_file() or path.stat().st_size>maximum:
        return None
    try:
        with path.open(encoding='utf-8-sig') as handle:
            return json.load(handle,parse_constant=lambda value: (_ for _ in ()).throw(ValueError('nonfinite JSON')))
    except (OSError,ValueError):
        return None


# Generated by GitHub Copilot - Oct-05-2026
def records(value,*keys):
    """Unwrap either a legacy list or an explicitly named collection envelope."""
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        for key in keys:
            if isinstance(value.get(key),list):
                return value[key]
    return None


