# Generated by GitHub Copilot - Oct-05-2026
def compare_runs(old,new):
    """Return descriptive deltas; claims of accuracy require annotated ground truth."""
    before,after=collect_run_metrics(old),collect_run_metrics(new)
    old_hash,new_hash=before['metrics']['source_hash'],after['metrics']['source_hash']
    same_source=bool(old_hash and new_hash and old_hash==new_hash)
    changes={}
    for key in sorted(set(before['metrics'])|set(after['metrics'])):
        left,right=before['metrics'].get(key),after['metrics'].get(key)
        numeric=all(isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value) for value in (left,right))
        changes[key]={'old':left,'new':right,'delta':right-left if numeric else None,
                      'comparison_status':'measured' if left is not None and right is not None else 'missing_evidence'}
        if before['metrics'].get('execution_scope') != after['metrics'].get('execution_scope') and any(term in key for term in ('runtime', 'seconds', 'semantic_inference_call_count', 'total_inference_call_count')):
            changes[key]['delta'] = None
            changes[key]['comparison_status'] = 'not_comparable_execution_scope'
    return {'schema_version':'1.0','same_source_confirmed':same_source,
            'comparison_type':'descriptive_artifact_comparison_not_accuracy_validation',
            'old':before,'new':after,'changes':changes,
            'limitations':['Sem rerun do mesmo video nao ha melhoria runtime comprovada.',
                           'Sem anotacoes nao ha medida de acuracia.',
                           'Arquivo omitido pelo review exporter nao prova ausencia no run original.']}


# Generated by GitHub Copilot - Oct-05-2026
def comparison_markdown(report):
    """Render metrics only; never embed transcript or private benchmark passages."""
    lines=['# Comparacao De Execucoes','','Comparacao descritiva, nao validacao de acuracia.',
           '','Mesmo hash de fonte confirmado: '+str(report['same_source_confirmed']),
           '','| Metrica | OLD | NEW | Delta |','|---|---|---|---|']
    for name,change in report['changes'].items():
        if isinstance(change['old'],dict) or isinstance(change['new'],dict):
            continue
        lines.append('| '+name+' | '+str(change['old'])+' | '+str(change['new'])+' | '+str(change['delta'])+' |')
    lines.extend(['','## Limitacoes','',*['- '+item for item in report['limitations']]])
    return '\n'.join(lines)+'\n'


# Generated by GitHub Copilot - Oct-05-2026
def audit_existing_editorial(value):
    """Reprocess exported candidates only; no ASR/vision/LLM runtime or accuracy claim."""
    from ldporto.editorial import normalize_context,classify_content,rank_candidate,deduplicate_candidates,require_pt_br
    folder=analysis_folder(value)
    main=records(read_optional(folder,'main_moments.json'),'main_moments','candidates')
    if main is None:
        return {'status':'unavailable','reason':'main_moments_missing_in_review_package'}
    editorial=records(read_optional(folder,'editorial_moments.json'),'moments','editorial_moments') or []
    by_id={row.get('moment_id'):row for row in editorial if row.get('moment_id')}
    normalized=[]
    invalid=0
    for original in main:
        moment_id=original.get('moment_id')
        start,end=original.get('ideal_start'),original.get('ideal_end')
        if (not moment_id or not all(isinstance(time,(int,float)) and not isinstance(time,bool) and math.isfinite(time) for time in (start,end))
                or not 0<=start<end):
            invalid+=1
            continue
        literal=(original.get('core_moment') or {}).get('text') or by_id.get(moment_id,{}).get('text') or ''
        evidence=original.get('evidence_segment_ids',[])
        classification=classify_content(literal,evidence)
        row={**original,**normalize_context(original),'text':literal,'commercial_classification':classification,
             'content_type':classification['content_type'],'commercial_score':classification['commercial_score']}
        normalized.append(rank_candidate(row))
    deduped,metrics=deduplicate_candidates(normalized)
    review=read_optional(folder,'ollama_editorial_review.json') or {}
    wrong_language=None
    if isinstance(review,dict) and review.get('overview'):
        try:
            require_pt_br([review['overview']])
            wrong_language=False
        except ValueError:
            wrong_language=True
    return {'status':'measured_from_existing_review_artifacts','evidence_kind':'offline_rules_applied_to_real_exported_candidates',
            'new_video_runtime_executed':False,'asr_vision_llm_rerun':False,'accuracy_ground_truth':'not_supplied',
            'candidate_metrics':metrics,'invalid_candidate_count':invalid,
            'context_enum_values':sorted({row['context_requirement'] for row in normalized}),
            'commercial_candidate_count_before_dedup':sum(row['content_type'] in ('advertisement','sponsor_read','merchandising') for row in normalized),
            'commercial_candidate_count_after_dedup':sum(row['content_type'] in ('advertisement','sponsor_read','merchandising') for row in deduped),
            'editorial_shortlist_eligible_count':sum(row['default_shortlist_eligible'] for row in deduped),
            'legacy_global_review_language_rejected':wrong_language,
            'candidate_ids_after_dedup':[row['moment_id'] for row in deduped],
            'candidate_ids_reference_scope':'original_review_main_moments.json',
            'no_transcript_copied_into_report':True}


# Generated by GitHub Copilot - Oct-05-2026
def main():
    """Write comparison artifacts outside both read-only input directories."""
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('old')
    parser.add_argument('new')
    parser.add_argument('--output-dir',default='benchmark_comparison')
    parser.add_argument('--audit-editorial',action='store_true',help='Aplicar regras deterministicas aos candidatos exportados, sem rerun do video')
    args=parser.parse_args()
    output=Path(args.output_dir).expanduser().resolve()
    for source in (analysis_folder(args.old),analysis_folder(args.new)):
        if output==source or source in output.parents:
            parser.error('A comparacao deve ser escrita fora das pastas de evidencia.')
    report=compare_runs(args.old,args.new)
    if args.audit_editorial:
        report['existing_editorial_audit']=audit_existing_editorial(args.old)
    output.mkdir(parents=True,exist_ok=True)
    write_json(output/'benchmark_comparison.json',report)
    (output/'benchmark_comparison.md').write_text(comparison_markdown(report),encoding='utf-8')
    print(output/'benchmark_comparison.md')
    return 0


if __name__=='__main__':
    try:
        raise SystemExit(main())
    except (OSError,ValueError) as exc:
        print(scrub(exc),file=sys.stderr)
        raise SystemExit(1)